#!/bin/bash
# Uninstall script for PS Remote Play
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling PS Remote Play..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

